        db,
        { key: 'database-error-key', payload: { value: 1 } },
        fixedNow
      )
    ).rejects.toBe(databaseError)

    expect(db.findByKey).toHaveBeenCalledTimes(1)
    expect(db.insert).toHaveBeenCalledTimes(1)
  })

