    const key = 'pending-insert-cache-probe'

    let finishInsert!: () => void
    const pendingInsert = new Promise<void>((resolve) => {
      finishInsert = () => resolve()
    })

    let markInsertStarted!: () => void
    const insertStarted = new Promise<void>((resolve) => {
      markInsertStarted = () => resolve()
    })

    const db = {
      findByKey: vi.fn(
        async (_key: string): Promise<StoredJob | null> => null
      ),
      insert: vi.fn((_job: StoredJob): Promise<void> => {
        markInsertStarted()
        return pendingInsert
      }),
    }

    const cacheSet = vi.spyOn(Map.prototype, 'set')
    const writesForKey = () =>
      cacheSet.mock.calls.filter(([writtenKey]) => writtenKey === key)

    const creation = createJob(
      db,
      { key, payload: { value: 1 } },
      fixedNow
    )

    await insertStarted

    expect(db.insert).toHaveBeenCalledTimes(1)
    expect(writesForKey()).toHaveLength(0)

    finishInsert()
    const result = await creation
    const writes = writesForKey()

    expect(writes).toHaveLength(1)
    expect(writes[0]?.[1]).toEqual({
      id: result.id,
      key,
      payload: '{"value":1}',
      createdAt: CREATED_AT,
    })
  })
})
