    expect(db.insert).toHaveBeenCalledTimes(2)
    expect(db.findByKey).toHaveBeenCalledTimes(3)
    expect(firstResult).toStrictEqual(publicJob(winner))
    expect(secondResult).toStrictEqual(publicJob(winner))
    expect(firstResult).not.toHaveProperty('payload')
    expect(secondResult).not.toHaveProperty('payload')
  })

