    const uniqueError = {
      code: 'UNIQUE_KEY' as const,
      marker: Symbol('original-error'),
    }

    const db = {
      findByKey: vi.fn(
        async (_key: string): Promise<StoredJob | null> => null
      ),
      insert: vi.fn(async (_job: StoredJob): Promise<void> => {
        throw uniqueError
      }),
    }

    await expect(
      createJob(db, { key: 'missing-winner', payload: {} })
    ).rejects.toBe(uniqueError)

    expect(db.findByKey).toHaveBeenCalledTimes(2)
  })

  it('preserves a non-unique insertion error unchanged', async () => {
    const databaseError = Object.assign(new Error('database unavailable'), {
      code: 'CONNECTION_LOST',
    })

    const db = {
      findByKey: vi.fn(
        async (_key: string): Promise<StoredJob | null> => null
      ),
      insert: vi.fn(async (_job: StoredJob): Promise<void> => {
        throw databaseError
      }),
    }

    await expect(
      createJob(db, { key: 'database-error', payload: {} })
    ).rejects.toBe(databaseError)

    expect(db.findByKey).toHaveBeenCalledTimes(1)
  })

  it('does not update cache while an insertion is still pending', async () => {
    const key = 'pending-cache-write-7a932f09'
    const insertStarted = deferredVoid()
    const insertGate = deferredVoid()
    let inserted: StoredJob | undefined

    const db = {
      findByKey: vi.fn(
        async (_key: string): Promise<StoredJob | null> => null
      ),
      insert: vi.fn((job: StoredJob): Promise<void> => {
        inserted = job
        insertStarted.resolve()
        return insertGate.promise
      }),
    }

    const setSpy = vi.spyOn(Map.prototype, 'set')
    const operation = createJob(
      db,
      { key: ` ${key} `, payload: { pending: true } },
      () => new Date('2025-04-01T00:00:00.000Z')
    )

    try {
      await insertStarted.promise

      const pendingJob = inserted
      if (pendingJob === undefined) {
        throw new Error('insert did not receive a job')
      }

      const writesForKey = () =>
        setSpy.mock.calls.filter(([writtenKey]) => writtenKey === key)

      expect(writesForKey()).toHaveLength(0)

      insertGate.resolve()
      const result = await operation

      expect(
        writesForKey().some(
          ([, writtenValue]) => writtenValue === pendingJob
        )
      ).toBe(true)
      expect(result).toStrictEqual(publicJob(pendingJob))
    } finally {
      insertGate.resolve()
      await operation.catch(() => undefined)
      setSpy.mockRestore()
    }
  })
})
