describe('createJob', () => {
  beforeEach(() => {
    randomUUIDMock.mockReset()
    randomUUIDMock.mockReturnValue(UUID_A)
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('normalizes and serializes the input once, captures time once, and omits payload', async () => {
    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => null
    )
    const insert = vi.fn(async (_job: Job): Promise<void> => {})
    const payload = { answer: 42 }
    const now = vi.fn(() => new Date('2025-01-02T03:04:05.000Z'))
    const stringifySpy = vi.spyOn(JSON, 'stringify')

    const result = await createJob(
      { findByKey, insert },
      { key: '  alpha  ', payload },
      now
    )

    const payloadStringifications = stringifySpy.mock.calls.filter(
      ([value]) => value === payload
    )
    stringifySpy.mockRestore()

    expect(payloadStringifications).toHaveLength(1)
    expect(now).toHaveBeenCalledTimes(1)
    expect(randomUUIDMock).toHaveBeenCalledTimes(1)
    expect(findByKey).toHaveBeenCalledTimes(1)
    expect(findByKey).toHaveBeenCalledWith('alpha')
    expect(insert).toHaveBeenCalledTimes(1)
    expect(insert).toHaveBeenCalledWith({
      id: UUID_A,
      key: 'alpha',
      payload: '{"answer":42}',
      createdAt: '2025-01-02T03:04:05.000Z',
    })
    expect(result).toEqual({
      id: UUID_A,
      key: 'alpha',
      createdAt: '2025-01-02T03:04:05.000Z',
    })
    expect(result).not.toHaveProperty('payload')
  })

  it('rejects a blank normalized key and an undefined serialization', async () => {
    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => null
    )
    const insert = vi.fn(async (_job: Job): Promise<void> => {})
    const now = vi.fn(() => new Date())
    const toJSON = vi.fn(() => undefined)
    const payload = { toJSON }

    await expect(
      createJob(
        { findByKey, insert },
        { key: ' \t\n ', payload },
        now
      )
    ).rejects.toThrow()

    expect(toJSON).not.toHaveBeenCalled()

    await expect(
      createJob(
        { findByKey, insert },
        { key: 'valid-key', payload },
        now
      )
    ).rejects.toThrow()

    expect(toJSON).toHaveBeenCalledTimes(1)
    expect(findByKey).not.toHaveBeenCalled()
    expect(insert).not.toHaveBeenCalled()
    expect(now).not.toHaveBeenCalled()
    expect(randomUUIDMock).not.toHaveBeenCalled()
  })

  it('uses the database even when the cache contains an older value', async () => {
    const key = 'database-authority'

    const warmFind = vi.fn(
      async (_key: string): Promise<Job | null> => null
    )
    const warmInsert = vi.fn(async (_job: Job): Promise<void> => {})

    await createJob(
      { findByKey: warmFind, insert: warmInsert },
      { key, payload: 'cached request' },
      () => new Date('2025-01-01T00:00:00.000Z')
    )

    const existing: Job = {
      id: 'database-row',
      key,
      payload: '"stored payload"',
      createdAt: '2024-12-01T00:00:00.000Z',
    }
    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => existing
    )
    const insert = vi.fn(async (_job: Job): Promise<void> => {})
    const cacheSet = vi.spyOn(Map.prototype, 'set')

    const result = await createJob(
      { findByKey, insert },
      { key, payload: 'new request' },
      () => new Date('2025-02-01T00:00:00.000Z')
    )

    const writesForKey = cacheSet.mock.calls.filter(
      ([cachedKey]) => cachedKey === key
    )
    cacheSet.mockRestore()

    expect(findByKey).toHaveBeenCalledTimes(1)
    expect(findByKey).toHaveBeenCalledWith(key)
    expect(insert).not.toHaveBeenCalled()
    expect(writesForKey).toHaveLength(1)
    expect(writesForKey[0]?.[1]).toEqual(existing)
    expect(result).toEqual({
      id: existing.id,
      key: existing.key,
      createdAt: existing.createdAt,
    })
    expect(result).not.toHaveProperty('payload')
  })

  it('resolves a concurrent-key race by rereading and returning the winner', async () => {
    const key = 'concurrent-key'
    const state: { row: Job | null } = { row: null }
    const uniqueError = Object.assign(new Error('lost key race'), {
      code: 'UNIQUE_KEY' as const,
    })

    let initialReadCount = 0
    let releaseInitialReads!: () => void
    const initialReadsReleased = new Promise<void>((resolve) => {
      releaseInitialReads = () => resolve()
    })

    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => {
        if (initialReadCount < 2) {
          initialReadCount += 1
          if (initialReadCount === 2) {
            releaseInitialReads()
          }

          await initialReadsReleased
          return null
        }

        return state.row
      }
    )

    const insert = vi.fn(async (job: Job): Promise<void> => {
      if (state.row !== null) {
        throw uniqueError
      }

      state.row = job
    })

    randomUUIDMock.mockReset()
    randomUUIDMock.mockReturnValue(UUID_A)
    randomUUIDMock.mockReturnValueOnce(UUID_A)
    randomUUIDMock.mockReturnValueOnce(UUID_B)

    const [left, right] = await Promise.all([
      createJob(
        { findByKey, insert },
        { key, payload: { caller: 'left' } },
        () => new Date('2025-03-01T00:00:00.000Z')
      ),
      createJob(
        { findByKey, insert },
        { key, payload: { caller: 'right' } },
        () => new Date('2025-03-01T00:00:01.000Z')
      ),
    ])

    const winner = state.row
    if (winner === null) {
      throw new Error('test database did not retain a winner')
    }

    const publicWinner = {
      id: winner.id,
      key: winner.key,
      createdAt: winner.createdAt,
    }

    expect(insert).toHaveBeenCalledTimes(2)
    expect(findByKey).toHaveBeenCalledTimes(3)
    expect(randomUUIDMock).toHaveBeenCalledTimes(2)
    expect(left).toEqual(publicWinner)
    expect(right).toEqual(publicWinner)
    expect(left).not.toHaveProperty('payload')
    expect(right).not.toHaveProperty('payload')
  })

  it('rethrows the original unique error when the reread finds no winner', async () => {
    const key = 'race-without-winner'
    const originalError = Object.assign(new Error('unique failure'), {
      code: 'UNIQUE_KEY' as const,
    })
    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => null
    )
    const insert = vi.fn(async (_job: Job): Promise<void> => {
      throw originalError
    })
    const cacheSet = vi.spyOn(Map.prototype, 'set')

    let thrown: unknown
    try {
      await createJob(
        { findByKey, insert },
        { key, payload: 'payload' },
        () => new Date('2025-04-01T00:00:00.000Z')
      )
    } catch (error) {
      thrown = error
    }

    const writesForKey = cacheSet.mock.calls.filter(
      ([cachedKey]) => cachedKey === key
    )
    cacheSet.mockRestore()

    expect(thrown).toBe(originalError)
    expect(findByKey).toHaveBeenCalledTimes(2)
    expect(writesForKey).toHaveLength(0)
  })

  it('preserves non-unique insertion errors without rereading', async () => {
    const originalError = new Error('database unavailable')
    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => null
    )
    const insert = vi.fn(async (_job: Job): Promise<void> => {
      throw originalError
    })

    await expect(
      createJob(
        { findByKey, insert },
        { key: 'non-unique-error', payload: 'payload' },
        () => new Date('2025-05-01T00:00:00.000Z')
      )
    ).rejects.toBe(originalError)

    expect(findByKey).toHaveBeenCalledTimes(1)
  })

  it('does not update the cache while an insert is pending', async () => {
    const key = 'pending-insert'

    let signalInsertStarted!: () => void
    const insertStarted = new Promise<void>((resolve) => {
      signalInsertStarted = () => resolve()
    })

    let resolveInsert!: () => void
    const insertGate = new Promise<void>((resolve) => {
      resolveInsert = () => resolve()
    })

    const findByKey = vi.fn(
      async (_key: string): Promise<Job | null> => null
    )
    const insert = vi.fn((_job: Job): Promise<void> => {
      signalInsertStarted()
      return insertGate
    })
    const cacheSet = vi.spyOn(Map.prototype, 'set')

    const pending = createJob(
      { findByKey, insert },
      { key, payload: { value: 1 } },
      () => new Date('2025-06-01T00:00:00.000Z')
    )

    await insertStarted

    const candidate = insert.mock.calls[0]![0]
    const writesBeforeSuccess = cacheSet.mock.calls.filter(
      ([cachedKey]) => cachedKey === key
    )

    resolveInsert()
    const result = await pending

    const writesAfterSuccess = cacheSet.mock.calls.filter(
      ([cachedKey]) => cachedKey === key
    )
    cacheSet.mockRestore()

    expect(writesBeforeSuccess).toHaveLength(0)
    expect(writesAfterSuccess).toHaveLength(1)
    expect(writesAfterSuccess[0]?.[1]).toEqual(candidate)
    expect(result).toEqual({
      id: candidate.id,
      key: candidate.key,
      createdAt: candidate.createdAt,
    })
    expect(result).not.toHaveProperty('payload')
  })
})
